<script setup>
import { ref } from 'vue'
import { questionnaire as form } from '../questionnaire.js'
const includeSample=ref(true), shared=ref('')
const patterns=[{text:'Shooting abdominal pain and migraines in the week leading up to the period, recurring at the end.',count:4,pain:4},{text:'Cramps and bloating through the first days of every period.',count:6,pain:3},{text:'Heavy bleeding with back pain and nausea in the first two days of the period.',count:2,pain:4},{text:'Mood swings and fatigue before bleeding, easing once the period starts. Sleep under 7 hours in the two heaviest cycles.',count:4,pain:2}]
function textSummary(){return `HerHealth — Summary for your healthcare professional\nSample cycle data · Apr–Oct 2026\n\n${patterns.map(p=>`${p.text} (${p.count}/6 cycles; pain ${p.pain}/5)`).join('\n\n')}\n\nSolutions explored: ${form.solutions.join(', ')||'None selected'}\nMedication: ${form.medications.filter(m=>includeSample.value||!m.source.includes('NHS')).map(m=>`${m.name}, ${m.frequency}`).join('; ')||'None added'}\n${includeSample.value?'Other conditions (sample): Hay fever since 2015; iron deficiency (resolved); penicillin allergy.':''}\nImpact on daily life: ${form.impact}/5\nNotes: ${form.notes||'None added'}\n\nBased on self-reported logs and sample data. Not a diagnosis.`}
async function share(){try{if(navigator.share){await navigator.share({title:'HerHealth summary',text:textSummary()});shared.value='Share sheet opened. No GP connection is configured.'}else if(navigator.clipboard){await navigator.clipboard.writeText(textSummary());shared.value='Summary copied. You can paste it into a message to your clinician.'}else download()}catch(e){if(e.name!=='AbortError')shared.value='Sharing is unavailable. Download a text copy instead.'}}
function download(){const url=URL.createObjectURL(new Blob([textSummary()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='herhealth-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function print(){window.print()}
</script>
<template><div class="design-screen stack summary-page"><header class="page-header"><a class="icon-btn" href="#questions" aria-label="Back to questions">‹</a><div><h1>Summary</h1><p class="muted">For your healthcare professional</p></div></header><p class="sample-label">Sample cycle data · Apr – Oct 2026</p>
<section class="card"><div class="section-link"><h2>Patterns identified</h2><span class="muted">Occurrences</span></div><div v-for="p in patterns" :key="p.text" class="pattern"><div><p>{{p.text}}</p><span class="pain">Pain <b>{{p.pain}}/5</b><span aria-hidden="true"> {{'●'.repeat(p.pain)}}{{'○'.repeat(5-p.pain)}}</span></span></div><div class="count"><strong>{{p.count}}</strong><span>of 6 cycles</span></div></div></section>
<section class="card"><h2>Effect on daily life</h2><div class="impact-score">{{form.impact}}<small>/ 5</small></div><p v-if="form.notes" class="notes">{{form.notes}}</p><p v-else class="muted">No additional notes added. <a href="#questions"><u>Add your experience</u></a></p></section>
<section class="card"><h2>Solutions already explored</h2><div class="chip-row"><span v-for="s in form.solutions" :key="s" class="chip">{{s}}</span><p v-if="!form.solutions.length" class="muted">None selected</p></div></section>
<section class="card"><h2>Current medication</h2><div v-for="med in form.medications.filter(m=>includeSample||!m.source.includes('NHS'))" :key="med.name" class="med"><div><strong>{{med.name}}</strong><span>{{med.frequency}}</span></div><small>{{med.source}}</small></div><p v-if="!form.medications.length" class="muted">No medication added</p></section>
<section class="card"><div class="section-link"><div><h2>From your NHS App</h2><p class="muted">Sample data only · No live NHS connection</p></div><button class="switch no-print" role="switch" :aria-checked="includeSample" aria-label="Include sample NHS App data in the summary" @click="includeSample=!includeSample"><span :class="{on:includeSample}"></span></button></div><template v-if="includeSample"><div class="med"><strong>Hay fever</strong><span class="muted">Since 2015</span></div><div class="med"><strong>Iron deficiency</strong><span class="muted">2023 · resolved</span></div><div class="med"><strong>Allergy: penicillin</strong><span class="muted">Sample record</span></div></template></section>
<div class="summary-actions no-print"><button class="primary" @click="share">Share summary</button><button class="secondary" @click="print">Print / Save PDF</button><button class="text-button" @click="download">Download text copy</button><p v-if="shared" role="status" class="notice">{{shared}}</p></div><p class="muted footnote">Based on self-reported logs and sample data. Not a diagnosis.<br>Nothing is sent automatically.</p></div></template>
<style scoped>
.summary-page{background:#f4ecdd!important}.page-header{justify-content:flex-start}.sample-label{font-size:10px;color:#84785e;margin:0 20px}.pattern{display:grid;grid-template-columns:1fr 70px;gap:15px;border-top:1px solid #e6e8f3;padding:17px 0}.pattern p{font-size:12px;line-height:1.8;margin:0 0 10px}.count{text-align:center;padding-top:4px}.count strong{display:block;font-size:25px;color:#3552c9}.count span{font-size:10px;color:#5a5f85}.pain{font-size:10px;color:#a3234a}.pain b{margin-left:4px}.pain>span{letter-spacing:2px;margin-left:7px}.impact-score{font-size:30px;color:#85609d;font-weight:800}.impact-score small{font-size:14px;font-weight:400}.notes{white-space:pre-wrap;font-size:13px;line-height:1.8}.med{display:flex;justify-content:space-between;gap:12px;padding:13px 0;border-top:1px solid #e6e8f3;font-size:12px}.med strong{font-size:12px}.med div>span{display:block;color:#5a5f85;font-size:11px;margin-top:4px}.med small{font-size:10px;color:#5a5f85;text-align:right;max-width:90px}.switch{background:none;border:0;width:54px;height:44px}.switch>span{display:block;width:44px;height:26px;border-radius:20px;background:#9aa0c4;padding:3px}.switch>span:after{content:'';display:block;width:20px;height:20px;border-radius:50%;background:white}.switch>span.on{background:#3552c9}.switch>span.on:after{transform:translateX(18px)}.summary-actions{display:flex;flex-wrap:wrap;gap:10px;margin:0 14px}.summary-actions>.primary,.summary-actions>.secondary{flex:1}.text-button{width:100%;padding:10px;border:0;background:none;font-size:12px;text-decoration:underline;color:#56318a}.footnote{text-align:center;font-size:10px}.section-link h2{margin-bottom:6px}.section-link p{font-size:10px}
</style>
